def diceCombinations(d: int, target: int) -> list[list[int]]:
    res = []
    def backtrack(dice_left, curr_sum, path):
        if dice_left == 0:
            if curr_sum == target:
                res.append(list(path))
            return
        for face in range(1, 7):
            if curr_sum + face + (dice_left - 1) * 1 <= target <= curr_sum + face + (dice_left - 1) * 6:
                backtrack(dice_left - 1, curr_sum + face, path + [face])
    backtrack(d, 0, [])
    return res

